('software-engineer', 'teknologi', 'Teknologi', 'Technology', 'Software Engineer / Programmer', 'Software Engineer / Programmer', 'Merancang, mengembangkan, dan memelihara aplikasi lunak, sistem web, dan arsitektur perangkat lunak menggunakan bahasa pemrograman modern.', 'Designs, develops, and maintains software applications, web systems, and software architecture using modern programming languages.', 8000000, 28000000, 'S1 Teknik Informatika / Sistem Informasi / Self-taught Bootcamp', 'Bachelor of Computer Science / Information Systems / Coding Bootcamp', '["JavaScript/TypeScript","React / Next.js","Python / Node.js","SQL & Database Design","Git & CI/CD","System Architecture"]'::jsonb, '["JavaScript/TypeScript","React / Next.js","Python / Node.js","SQL & Database Design","Git & CI/CD","System Architecture"]'::jsonb, 'Fleksibel (Remote / Hybrid / WFO), kantor startup atau perusahaan teknologi modern.', 'Flexible (Remote / Hybrid / WFO), startup offices or modern tech companies.', 'Junior Engineer -> Mid-Level Engineer -> Senior Engineer -> Tech Lead -> Engineering Manager / Software Architect', 'Junior Engineer -> Mid-Level Engineer -> Senior Engineer -> Tech Lead -> Engineering Manager / Software Architect', 'high', 4, 'https://images.unsplash.com/photo-1498050108023-c5249f4df085?q=80&w=800&auto=format&fit=crop', true, '[{"code":"INTJ","match_score":95,"reason_id":"Pendekatan analitis dan pemikiran sistemik sangat cocok dengan arsitektur software.","reason_en":"Analytical mindset and system architecture skills align perfectly with software engineering."},{"code":"INTP","match_score":98,"reason_id":"Suka memecahkan algoritma rumit dan bereksperimen dengan teknologi baru.","reason_en":"Loves solving complex algorithms and experimenting with novel tech stacks."},{"code":"ISTP","match_score":90,"reason_id":"Sangat terampil menggunakan alat praktis dan debugging teknis secara cepat.","reason_en":"Exceptional at using practical tools and rapid technical debugging."}]'::jsonb),
('data-scientist', 'teknologi', 'Teknologi', 'Technology', 'Data Scientist', 'Data Scientist', 'Menganalisis himpunan data besar (big data), membangun model Machine Learning, dan memberikan wawasan prediktif untuk keputusan bisnis.', 'Analyzes big data sets, builds Machine Learning models, and delivers predictive insights for strategic business decisions.', 10000000, 30000000, 'S1 Matematika / Statistika / Ilmu Komputer / Data Science', 'Bachelor of Mathematics / Statistics / Computer Science / Data Science', '["Python & R","Machine Learning & AI","SQL & BigData","Data Visualization","Statistical Analysis"]'::jsonb, '["Python & R","Machine Learning & AI","SQL & BigData","Data Visualization","Statistical Analysis"]'::jsonb, 'Kantor Korporat, FinTech, E-Commerce, konsultan data analytics.', 'Corporate offices, FinTech, E-Commerce platforms, data analytics consultancies.', 'Junior Data Analyst -> Data Scientist -> Senior Data Scientist -> Principal Data Scientist -> Head of Data', 'Junior Data Analyst -> Data Scientist -> Senior Data Scientist -> Principal Data Scientist -> Head of Data', 'high', 4, 'https://images.unsplash.com/photo-1551288049-bebda4e38f71?q=80&w=800&auto=format&fit=crop', true, '[{"code":"INTJ","match_score":97,"reason_id":"Sangat ahli dalam memodelkan pola tersembunyi dari himpunan data rumit.","reason_en":"Excels in modeling hidden patterns out of complex data sets."},{"code":"INTP","match_score":96,"reason_id":"Kreativitas analitis tinggi dalam menguji hipotesis statistik.","reason_en":"High analytical creativity in testing statistical hypotheses."},{"code":"ISTJ","match_score":88,"reason_id":"Ketelitian tinggi terhadap kebersihan data dan keakuratan angka.","reason_en":"High precision regarding data cleanliness and numerical accuracy."}]'::jsonb),
('cybersecurity-specialist', 'teknologi', 'Teknologi', 'Technology', 'Spesialis Keamanan Siber', 'Information Security Analyst', 'Memantau, mencegah, dan menangkal serangan siber pada jaringan data, server korporat, dan infrastruktur sistem informasi.', 'Monitors, prevents, and mitigates cyber attacks on computer networks, corporate servers, and critical infrastructure systems.', 9000000, 32000000, 'S1 Keamanan Siber / Teknik Informatika / Sertifikasi CEH/CISSP', 'Bachelor of Cyber Security / Computer Science / CEH/CISSP Certification', '["Penetration Testing","Network Security","Cryptography","Incident Response","SIEM Tools","Security Auditing"]'::jsonb, '["Penetration Testing","Network Security","Cryptography","Incident Response","SIEM Tools","Security Auditing"]'::jsonb, 'Security Operation Center (SOC), perbankan, instansi pemerintah, atau konsultan audit.', 'Security Operation Centers (SOC), banking institutions, government defense, or audit firms.', 'SOC Analyst -> Security Engineer -> Penetration Tester -> Chief Information Security Officer (CISO)', 'SOC Analyst -> Security Engineer -> Penetration Tester -> Chief Information Security Officer (CISO)', 'high', 3, 'https://images.unsplash.com/photo-1563986768609-322da13575f3?q=80&w=800&auto=format&fit=crop', false, '[{"code":"ISTJ","match_score":95,"reason_id":"Kepatuhan ketat terhadap protokol pertahanan dan ketelitian pemantauan anomali.","reason_en":"Rigorous adherence to defense protocols and high diligence in spotting anomalies."},{"code":"INTJ","match_score":94,"reason_id":"Kemampuan memprediksi taktik penyerang secara strategis dan sistematis.","reason_en":"Ability to predict adversary attack vectors strategically and systematically."},{"code":"INTP","match_score":91,"reason_id":"Suka membedah kerentanan kode dan mencari solusi eksploitasi teknis.","reason_en":"Enjoys dissecting vulnerabilities and finding novel technical solutions."}]'::jsonb),
('cloud-solutions-architect', 'teknologi', 'Teknologi', 'Technology', 'Cloud Solutions Architect', 'Cloud Solutions Architect', 'Merancang strategi adopsi cloud, merancang infrastruktur komputasi awan yang terukur, aman, dan efisien biaya bagi korporasi.', 'Architects enterprise cloud adoption strategies, designing scalable, secure, and cost-optimized cloud infrastructure.', 15000000, 42000000, 'S1 Teknik Komputer / Informatika + Sertifikasi AWS/GCP/Azure Architect', 'Bachelor of Computer Engineering + AWS/GCP/Azure Solutions Architect Certified', '["AWS / Azure / GCP","Terraform & IaC","Kubernetes & Docker","High Availability Architecture","FinOps","Disaster Recovery"]'::jsonb, '["AWS / Azure / GCP","Terraform & IaC","Kubernetes & Docker","High Availability Architecture","FinOps","Disaster Recovery"]'::jsonb, 'Perusahaan multinasional, penyedia layanan cloud, atau teknologi finansial besar.', 'Multinational tech companies, cloud service providers, or major FinTech firms.', 'Cloud Engineer -> Senior DevOps -> Cloud Architect -> Principal Enterprise Architect', 'Cloud Engineer -> Senior DevOps -> Cloud Architect -> Principal Enterprise Architect', 'high', 4, 'https://images.unsplash.com/photo-1451187580459-43490279c0fa?q=80&w=800&auto=format&fit=crop', false, '[{"code":"ENTJ","match_score":94,"reason_id":"Visi arsitektur skala besar dan kepemimpinan dalam transformasi digital.","reason_en":"Large-scale architectural vision and leadership in digital transformations."},{"code":"INTJ","match_score":96,"reason_id":"Pemikiran konseptual mendalam tentang keandalan sistem jangka panjang.","reason_en":"Deep conceptual thinking regarding long-term system reliability."},{"code":"ESTJ","match_score":89,"reason_id":"Disiplin tinggi dalam menegakkan kepatuhan keamanan dan anggaran infrastruktur.","reason_en":"High discipline enforcing security compliance and infrastructure budgets."}]'::jsonb),
('devops-engineer', 'teknologi', 'Teknologi', 'Technology', 'DevOps Engineer', 'DevOps Engineer', 'Menjembatani tim pengembangan dan operasional dengan mengotomasi pipeline pengiriman software, monitoring performa, dan pengelolaan server.', 'Bridges software development and IT operations through automated delivery pipelines, performance monitoring, and server orchestration.', 9000000, 27000000, 'S1 Ilmu Komputer / Teknik Telekomunikasi / Praktisi Sistem Linux', 'Bachelor of Computer Science / Telecommunication Engineering / Linux Practitioner', '["Linux Administration","Docker & Kubernetes","CI/CD Pipelines","Ansible / Terraform","Prometheus & Grafana","Bash Scripting"]'::jsonb, '["Linux Administration","Docker & Kubernetes","CI/CD Pipelines","Ansible / Terraform","Prometheus & Grafana","Bash Scripting"]'::jsonb, 'Startup teknologi, software house, perbankan modern.', 'Tech startups, software agencies, modern digital banking.', 'Junior Sysadmin -> DevOps Engineer -> Senior Platform Engineer -> Head of Infrastructure', 'Junior Sysadmin -> DevOps Engineer -> Senior Platform Engineer -> Head of Infrastructure', 'high', 4, 'https://images.unsplash.com/photo-1618401471353-b98aedd04e11?q=80&w=800&auto=format&fit=crop', false, '[{"code":"ISTP","match_score":95,"reason_id":"Pragmatisme teknis dan keahlian pemecahan masalah instan pada sistem server.","reason_en":"Technical pragmatism and rapid problem-solving during server outages."},{"code":"ISTJ","match_score":93,"reason_id":"Fokus konsisten pada kestabilan sistem dan otomatisasi berulang yang rapi.","reason_en":"Consistent focus on system uptime and reliable routine automation."},{"code":"INTP","match_score":90,"reason_id":"Ketertarikan menyederhanakan alur kerja kompleks menjadi script otomatis.","reason_en":"Interest in streamlining complex workflows into automated scripts."}]'::jsonb),
