('database-administrator', 'teknologi', 'Teknologi', 'Technology', 'Database Administrator (DBA)', 'Database Administrator', 'Mengelola integritas, keamanan, ketersediaan, dan optimasi performa basis data korporat berskala gigabyte hingga petabyte.', 'Ensures the integrity, security, high availability, and query performance optimization of corporate database clusters.', 7500000, 22000000, 'S1 Sistem Informasi / Ilmu Komputer / Sertifikasi Oracle/PostgreSQL', 'Bachelor of Information Systems / Computer Science / Oracle/PostgreSQL Certified', '["PostgreSQL & MySQL","NoSQL (MongoDB/Redis)","Database Indexing & Tuning","Backup & Replication","Data Security","Data Warehousing"]'::jsonb, '["PostgreSQL & MySQL","NoSQL (MongoDB/Redis)","Database Indexing & Tuning","Backup & Replication","Data Security","Data Warehousing"]'::jsonb, 'Pusat data korporat, perbankan, telekomunikasi, e-commerce.', 'Corporate data centers, banking institutions, telecom, large e-commerce.', 'Junior DBA -> Senior DBA -> Database Architect -> Head of Data Infrastructure', 'Junior DBA -> Senior DBA -> Database Architect -> Head of Data Infrastructure', 'medium', 4, 'https://images.unsplash.com/photo-1544383835-bda2bc66a55d?q=80&w=800&auto=format&fit=crop', false, '[{"code":"ISTJ","match_score":96,"reason_id":"Ketelitian nomor satu dalam menjaga keutuhan data dan keteraturan skema.","reason_en":"Top-tier precision safeguarding data consistency and schema orderliness."},{"code":"ESTJ","match_score":90,"reason_id":"Ketegasan menegakkan tata kelola data dan kebijakan akses aman.","reason_en":"Firm enforcement of data governance and security access policies."},{"code":"INTJ","match_score":89,"reason_id":"Kemampuan memetakan struktur relasional data yang efisien dan bersih.","reason_en":"Skill in designing highly efficient, clean relational data structures."}]'::jsonb),
('mobile-app-developer', 'teknologi', 'Teknologi', 'Technology', 'Mobile Application Developer', 'Mobile Application Developer', 'Membangun dan mempublikasikan aplikasi mobile berperforma tinggi untuk platform Android dan iOS menggunakan Flutter, React Native, Kotlin, atau Swift.', 'Builds and publishes responsive mobile applications for Android and iOS using Flutter, React Native, Kotlin, or Swift.', 7500000, 25000000, 'S1 Teknik Informatika / Portofolio Aplikasi di Google Play & App Store', 'Bachelor of Computer Science / Live App Portfolio on App Stores', '["Flutter / React Native","Kotlin / Swift","Mobile UI State Management","Offline Caching & SQLite","API Integration","App Store Deployment"]'::jsonb, '["Flutter / React Native","Kotlin / Swift","Mobile UI State Management","Offline Caching & SQLite","API Integration","App Store Deployment"]'::jsonb, 'Startup aplikasi consumer, studio software, tim produk digital.', 'Consumer app startups, digital product agencies, tech product teams.', 'Junior Mobile Dev -> Senior Mobile Dev -> Mobile Tech Lead -> Head of Mobile Engineering', 'Junior Mobile Dev -> Senior Mobile Dev -> Mobile Tech Lead -> Head of Mobile Engineering', 'high', 4, 'https://images.unsplash.com/photo-1555774698-0b77e0d5fac6?q=80&w=800&auto=format&fit=crop', false, '[{"code":"ISTP","match_score":94,"reason_id":"Keahlian menyelaraskan komponen perangkat keras ponsel dengan kode efisien.","reason_en":"Skill aligning smartphone hardware capabilities with efficient code."},{"code":"INTP","match_score":92,"reason_id":"Gemar mencari cara elegan mengelola state aplikasi yang kompleks.","reason_en":"Enjoys elegant solutions for managing complex client-side application states."},{"code":"ENFP","match_score":87,"reason_id":"Sensitivitas tinggi terhadap kelancaran animasi dan sensasi sentuhan pengguna.","reason_en":"High sensitivity to smooth micro-animations and intuitive touch interactions."}]'::jsonb),
('qa-automation-engineer', 'teknologi', 'Teknologi', 'Technology', 'QA Automation Engineer', 'Quality Assurance Automation Engineer', 'Merancang script tes otomatis dan skenario pengujian beban untuk memastikan perangkat lunak bebas bug sebelum dirilis ke pengguna.', 'Designs automated test suites and load testing scenarios to ensure software releases are robust, stable, and bug-free.', 7000000, 20000000, 'S1 Ilmu Komputer / Penguji Perangkat Lunak Tersertifikasi ISTQB', 'Bachelor of Computer Science / ISTQB Certified Software Tester', '["Cypress / Playwright","Selenium","API Testing (Postman/K6)","Continuous Testing","Defect Tracking","Performance Testing"]'::jsonb, '["Cypress / Playwright","Selenium","API Testing (Postman/K6)","Continuous Testing","Defect Tracking","Performance Testing"]'::jsonb, 'Kantor teknologi, tim rekayasa perangkat lunak, sistem perbankan.', 'Tech companies, software development teams, high-availability banking.', 'Manual QA -> QA Automation Engineer -> Lead QA -> Head of Quality Engineering', 'Manual QA -> QA Automation Engineer -> Lead QA -> Head of Quality Engineering', 'high', 4, 'https://images.unsplash.com/photo-1517694712202-14dd9538aa97?q=80&w=800&auto=format&fit=crop', false, '[{"code":"ISTJ","match_score":97,"reason_id":"Mata elang mendeteksi inkonsistensi terkecil dan kepatuhan pada kriteria lulus uji.","reason_en":"Sharp eye detecting minor regressions and rigorous adherence to acceptance criteria."},{"code":"ISFJ","match_score":91,"reason_id":"Rasa tanggung jawab tinggi melindungi kenyamanan dan keamanan pengguna akhir.","reason_en":"High sense of duty safeguarding end-user peace of mind and satisfaction."},{"code":"INTP","match_score":89,"reason_id":"Cerdik menemukan skenario ''edge case'' tak terduga yang lolos dari developer.","reason_en":"Ingenious at devising unforeseen edge cases that slip past developers."}]'::jsonb),
('dokter-umum', 'kesehatan', 'Kesehatan', 'Healthcare', 'Dokter Umum', 'General Practitioner / Physician', 'Melakukan pemeriksaan fisik, mendiagnosis penyakit, memberikan pengobatan dasar, serta memberikan edukasi kesehatan bagi pasien.', 'Examines physical health, diagnoses medical conditions, prescribes treatments, and promotes health education for patients.', 10000000, 35000000, 'S1 Kedokteran + Profesi Dokter (Koas) + STR Dokter', 'Bachelor of Medicine + Medical Residency + Physician License', '["Diagnosis Medis","Empati & Komunikasi Pasien","Tindakan Darurat Medis","Farmakologi","Anatomi"]'::jsonb, '["Medical Diagnosis","Patient Empathy & Communication","Emergency Procedures","Pharmacology","Anatomy"]'::jsonb, 'Rumah sakit, puskesmas, klinik swasta, dengan sistem shift kerja.', 'Hospitals, public health centers, private clinics with shift rotations.', 'Dokter PTT / Puskesmas -> Dokter Umum RS -> Dokter Spesialis -> Dokter Konsultan / Kepala Rumah Sakit', 'General Doctor -> Resident Physician -> Medical Specialist -> Hospital Consultant / Medical Director', 'high', 3, 'https://images.unsplash.com/photo-1537368910025-700350fe46c7?q=80&w=800&auto=format&fit=crop', true, '[{"code":"ISFJ","match_score":96,"reason_id":"Dedikasi tinggi, perhatian pada detail medis, dan empati hangat kepada pasien.","reason_en":"High dedication, attention to detail, and deep empathy for patients."},{"code":"ISTJ","match_score":92,"reason_id":"Sangat disiplin mengikuti protokol prosedur medis dan rekam medis akurat.","reason_en":"Disciplined in following medical protocols and maintaining accurate medical records."},{"code":"ENFJ","match_score":88,"reason_id":"Mampu menenangkan pasien dan memimpin tim perawat dengan menginspirasi.","reason_en":"Calms patients effectively and leads medical teams with inspiration."}]'::jsonb),
