('perawat', 'kesehatan', 'Kesehatan', 'Healthcare', 'Perawat (Registered Nurse)', 'Registered Nurse', 'Memberikan asuhan keperawatan intensif, memantau tanda vital pasien, mengelola infus dan obat, serta mendampingi pemulihan medis.', 'Provides primary patient care, monitors vital signs, administers intravenous medications, and coordinates patient recovery plans.', 5000000, 15000000, 'D3 Keperawatan / S1 Keperawatan + Profesi Ners', 'Associate Degree / Bachelor of Science in Nursing (BSN) + Registered Nurse License', '["Asuhan Keperawatan","Pemasangan Infus & Kateter","Resusitasi Jantung Paru (BCLS)","Pencatatan Rekam Medis","Empati Pasien"]'::jsonb, '["Patient Assessment","IV Infusion & Triage","Basic Life Support (BLS)","Clinical Documentation","Patient Empathy"]'::jsonb, 'Ruang rawat inap rumah sakit, IGD, ICU, panti jompo, klinik rawat jalan.', 'Hospital inpatient wards, Emergency Rooms, Intensive Care Units, outpatient clinics.', 'Perawat Pelaksana -> Perawat Primer -> Kepala Ruangan (Ward Head) -> Kepala Keperawatan Rumah Sakit', 'Staff Nurse -> Charge Nurse -> Unit Supervisor -> Chief Nursing Officer', 'high', 3, 'https://images.unsplash.com/photo-1576765608535-5f04d1e3f289?q=80&w=800&auto=format&fit=crop', false, '[{"code":"ISFJ","match_score":98,"reason_id":"Jiwa pengasuh alami (The Protector), sangat peka pada kebutuhan kenyamanan orang sakit.","reason_en":"Natural caregiver with supreme empathy for the comfort and relief of vulnerable patients."},{"code":"ESFJ","match_score":95,"reason_id":"Keahlian berkoordinasi hangat dengan keluarga pasien dan sesama rekan medis.","reason_en":"Warm collaboration coordinating effectively with patient families and clinical teams."},{"code":"ENFJ","match_score":89,"reason_id":"Kemampuan memotivasi semangat juang pasien yang sedang menghadapi penyakit berat.","reason_en":"Inspiring presence motivating recovery and perseverance in patients facing hardships."}]'::jsonb),
