('digital-archivist-librarian', 'pendidikan', 'Pendidikan', 'Education', 'Pustakawan Digital & Arsiparis', 'Librarian and Media Collections Specialist', 'Mengkurasi repositori literatur akademik, mendigitalkan naskah manuskrip bersejarah, serta memandu riset pencarian literatur ilmiah.', 'Curates digital academic repositories, preserves historical archival manuscripts, and assists researchers with scholarly metadata cataloging.', 5000000, 15000000, 'S1 Ilmu Perpustakaan dan Informasi / Manajemen Arsip', 'Master/Bachelor of Library and Information Science (MLIS)', '["Sistem Temu Balik Informasi (OPAC)","Metadata Dublin Core & MARC21","Preservasi Digital Manuskrip","Literasi Riset Informasi","Penyusunan Taksonomi"]'::jsonb, '["Information Retrieval Systems","Dublin Core & Metadata Cataloging","Digital Archive Preservation","Scholarly Research Guidance","Taxonomy Structuring"]'::jsonb, 'Perpustakaan nasional, repositori digital universitas, museum arsip negara.', 'National libraries, university research collections, state archival repositories.', 'Pustakawan Muda -> Kepala Koleksi Digital -> Direktur Sistem Perpustakaan -> Konsultan Arsip Nasional', 'Reference Librarian -> Head of Digital Collections -> Library Dean -> National Archival Director', 'medium', 5, 'https://images.unsplash.com/photo-1521587760476-6c12a4b040da?q=80&w=800&auto=format&fit=crop', false, '[{"code":"INTJ","match_score":96,"reason_id":"Kecintaan pada pengarsipan pengetahuan semesta secara terstruktur dan abadi.","reason_en":"Reverence for systematizing human knowledge into accessible, lasting digital frameworks."},{"code":"ISTJ","match_score":95,"reason_id":"Keteraturan mutlak dalam klasifikasi desimal dan ketelitian indeks buku tanpa salah.","reason_en":"Methodical mastery of classification decimals, catalog precision, and archival preservation."},{"code":"INFP","match_score":89,"reason_id":"Menikmati ketenangan lorong perpustakaan dan apresiasi puitis terhadap warisan literatur.","reason_en":"Cherishes the serene quiet of archives and poetic resonance of classic literary heritage."}]'::jsonb),
('motion-graphic-designer', 'seni-desain', 'Seni & Desain', 'Art & Design', 'Motion Graphic Designer', 'Motion Graphics Designer', 'Menggabungkan desain grafis, tipografi kinetik, dan animasi dinamis untuk iklan promosi digital, opening program TV, dan UI micro-interaction.', 'Blends graphic design, kinetic typography, and audio-synced motion animation for digital commercials, title sequences, and UI motion.', 6000000, 19000000, 'S1 DKV / Animasi / Media Digital / Showreel Motion Portofolio', 'Bachelor of Visual Communication / Motion Graphics Showreel Portfolio', '["After Effects & Cinema 4D","Kinetic Typography","Lottie & Web Motion","Audio Synchronization","Visual Effects Compositing"]'::jsonb, '["After Effects & Cinema 4D","Kinetic Typography","Lottie & Web Motion","Audio Synchronization","Visual Effects Compositing"]'::jsonb, 'Agensi kreatif, studio broadcast, perusahaan teknologi.', 'Creative broadcast studios, digital advertising agencies, tech product brand teams.', 'Motion Designer -> Senior Motion Lead -> Motion Art Director -> Creative Director', 'Motion Designer -> Senior Motion Lead -> Motion Art Director -> Creative Director', 'high', 4, 'https://images.unsplash.com/photo-1550745165-9bc0b252726f?q=80&w=800&auto=format&fit=crop', false, '[{"code":"ENFP","match_score":95,"reason_id":"Energi visual dinamis dan ritme animasi yang playful memikat perhatian penonton.","reason_en":"Dynamic visual rhythm and playful kinetic timing capturing audience attention instantly."},{"code":"ISFP","match_score":93,"reason_id":"Kepekaan harmonis pada kurva akselerasi gerak animasi (easing curves) yang mulus.","reason_en":"Flawless aesthetic sense for organic easing velocity and fluid animation physics."},{"code":"INTP","match_score":89,"reason_id":"Pemanfaatan ekspresi kode scripting After Effects untuk otomatisasi gerak prosedural.","reason_en":"Clever utilization of code expressions and procedural particle drivers in After Effects."}]'::jsonb),
